def extended_gcd(a, b):
    if a == 0:
        return (b, 0, 1)
    else:
        g, y, x = extended_gcd(b % a, a)
        return (g, x - (b // a) * y, y)

def solve(inputs: dict) -> float:
    REMS = inputs['REMAINDERS']
    MODS = inputs['MODULI']

    n = len(REMS)
    M = 1
    for mod in MODS:
        M *= mod

    x = 0
    for (i, REM) in enumerate(REMS):
        Mi = M // MODS[i]
        gcd, y, _ = extended_gcd(Mi, MODS[i])
        if gcd != 1:
            raise ValueError("Moduli are not pairwise coprime.")
        xi = REM * y * Mi
        x += xi % M

    return float(x % M)

